  .dirs{grid-template-columns:minmax(0,1fr)}
  .incl ul{grid-template-columns:repeat(2,minmax(0,1fr))}
  .foot .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .tests{gap:62px}
}
