  .mbar{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:20;background:var(--white);border-top:1px solid var(--line);box-shadow:0 -6px 20px rgba(0,0,40,.12);padding:10px max(16px,env(safe-area-inset-right,0px)) calc(10px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px));align-items:center;justify-content:space-between;gap:12px}
  .mbar b{display:block;font-size:20px;color:var(--navy);font-weight:900;line-height:1.1}
